package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.ProjectSites.Column;

/** Immutable authored layouts, rotation and conservative terrain fitting. */
public record BotSchematic(String name,List<List<String>> layers,Column anchor,Map<String,String> palette,List<String> tags,String purpose,String description,String groundMode,int maxFill,int baseLevel,Cell occupant,int maxBuilders,List<Local> cells,List<Cell> clear) {
    public record Local(int u,int f,int h,String color){}
    public static final Map<String,Integer> COLORS=Map.of("sand",0xc8b27a,"concrete",0x8c8c8c,"wood",0x8a5a2e,"dark",0x4a4a4a,"olive",0x6b7a3a,"brick",0x9a4a3a,"gold",0xd4af37,"stone",0x77736b);
    public static final int[][] FORWARD={{1,0},{0,1},{-1,0},{0,-1}};
    public BotSchematic{layers=layers.stream().map(List::copyOf).toList();palette=Map.copyOf(palette);tags=List.copyOf(tags);cells=List.copyOf(cells);clear=List.copyOf(clear);if(cells.isEmpty())throw new IllegalArgumentException("Empty schematic");if(!Set.of("fill","deck").contains(groundMode))throw new IllegalArgumentException("Unknown ground mode");}
    public static BotSchematic authored(String name,List<List<String>> layers,Column anchor,Map<String,String> palette,List<String> tags,String purpose,String description,String groundMode,int maxFill,int baseLevel,Cell occupant,int builders){var cells=new ArrayList<Local>();var clear=new ArrayList<Cell>();for(int h=0;h<layers.size();h++){var rows=layers.get(h);for(int row=0;row<rows.size();row++){var line=rows.get(row);for(int col=0;col<line.length();col++){char c=line.charAt(col);int u=col-anchor.x(),f=anchor.y()-row;if("#+=".indexOf(c)>=0){String token=palette.getOrDefault(String.valueOf(c),"team");if(!token.equals("team")&&!COLORS.containsKey(token))throw new IllegalArgumentException("Unknown palette "+token);cells.add(new Local(u,f,h+baseLevel,token));}else if(c=='_')clear.add(new Cell(u,f,h+baseLevel));else if(c!='.'&&c!=' ')throw new IllegalArgumentException("Unknown schematic legend "+c);}}}return new BotSchematic(name,layers,anchor,palette,tags,purpose,description,groundMode,maxFill,baseLevel,occupant,builders,cells,clear);}
    public int blockCount(){return cells.size();}public int height(){return cells.stream().mapToInt(Local::h).max().orElseThrow()+1;}
    public Set<Column> footprint(){var result=new LinkedHashSet<Column>();for(var c:cells)result.add(new Column(c.u(),c.f()));for(var c:clear)result.add(new Column(c.x(),c.y()));return Collections.unmodifiableSet(result);}public int radius(){return footprint().stream().mapToInt(c->Math.max(Math.abs(c.x()),Math.abs(c.y()))).max().orElseThrow();}
    public static int rotation(double dx,double dy){if(!Double.isFinite(dx)||!Double.isFinite(dy)||Math.abs(dx)+Math.abs(dy)<1e-9)return 0;int result=0;double best=Double.NEGATIVE_INFINITY;for(int i=0;i<4;i++){double dot=FORWARD[i][0]*dx+FORWARD[i][1]*dy;if(dot>best){best=dot;result=i;}}return result;}
    public static Column world(Column anchor,int rotation,int u,int f){var forward=FORWARD[Math.floorMod(rotation,4)];return new Column(anchor.x()-u*forward[1]+f*forward[0],anchor.y()+u*forward[0]+f*forward[1]);}
    public record Placement(BotSchematic schematic,Cell anchor,int rotation,Map<Cell,String> cells,Set<Cell> foundation,Set<Cell> clear,Set<Column> columns,Vector occupant){public Placement{cells=Collections.unmodifiableMap(new LinkedHashMap<>(cells));foundation=Set.copyOf(foundation);clear=Set.copyOf(clear);columns=Set.copyOf(columns);}public String name(){return schematic.name();}public int groundZ(){return anchor.z();}public int cost(){return cells.size();}public List<Integer> bounds(int margin){return List.of(columns.stream().mapToInt(Column::x).min().orElseThrow()-margin,columns.stream().mapToInt(Column::x).max().orElseThrow()+margin,columns.stream().mapToInt(Column::y).min().orElseThrow()-margin,columns.stream().mapToInt(Column::y).max().orElseThrow()+margin);}}
    public record Fit(Placement placement,String reason){}
    public Fit fit(RecoveryPlanning.World solid,Column xy,int ground,int rotation,int allowed){rotation=Math.floorMod(rotation,4);var cells=new LinkedHashMap<Cell,String>();var foundation=new HashSet<Cell>();var air=new HashSet<Cell>();var columns=new LinkedHashSet<Column>();var tops=new HashMap<Column,Integer>();var byColumn=new LinkedHashMap<Column,List<Local>>();var clearColumns=new LinkedHashMap<Column,List<Integer>>();for(var c:this.cells)byColumn.computeIfAbsent(new Column(c.u(),c.f()),k->new ArrayList<>()).add(c);for(var c:clear)clearColumns.computeIfAbsent(new Column(c.x(),c.y()),k->new ArrayList<>()).add(c.z());var all=new LinkedHashSet<>(byColumn.keySet());all.addAll(clearColumns.keySet());for(var local:all){var col=world(xy,rotation,local.x(),local.y());if(col.x()<1||col.x()>=511||col.y()<1||col.y()>=511)return new Fit(null,"out_of_map");columns.add(col);if(groundMode.equals("fill")){Integer top=null;for(int z=ground-3;z<=ground+3;z++)if(solid.solid(col.x(),col.y(),z)){top=z;break;}if(top==null||top<ground-1||top>ground+maxFill)return new Fit(null,"uneven_ground");tops.put(local,top);}}
        int obstructed=0;for(var e:byColumn.entrySet()){var local=e.getKey();var col=world(xy,rotation,local.x(),local.y());var top=tops.get(local);var entries=e.getValue();if(groundMode.equals("fill")&&top!=null&&top>ground){var lowest=entries.stream().min(Comparator.comparingInt(Local::h).thenComparing(Local::color)).orElseThrow();if(lowest.h()==0)for(int z=ground;z<top;z++){var c=new Cell(col.x(),col.y(),z);cells.put(c,lowest.color());foundation.add(c);}}for(var item:entries){int z=ground-1-item.h();if(z<1||z>238)return new Fit(null,"out_of_build_band");var c=new Cell(col.x(),col.y(),z);if(solid.solid(c)){if(item.h()>=1||groundMode.equals("deck"))obstructed++;continue;}cells.put(c,item.color());}}
        for(var e:clearColumns.entrySet()){var col=world(xy,rotation,e.getKey().x(),e.getKey().y());for(int h:e.getValue()){var c=new Cell(col.x(),col.y(),ground-1-h);if(solid.solid(c))return new Fit(null,"clearance_blocked");air.add(c);}}if(obstructed>allowed)return new Fit(null,"obstructed");if(cells.isEmpty())return new Fit(null,"already_built");if(!Collections.disjoint(air,cells.keySet()))return new Fit(null,"clearance_conflict");Vector body=null;if(occupant!=null){var col=world(xy,rotation,occupant.x(),occupant.y());body=new Vector(col.x()+.5,col.y()+.5,ground-occupant.z()-2.25);}return new Fit(new Placement(this,new Cell(xy.x(),xy.y(),ground),rotation,cells,foundation,air,columns,body),"");
    }
    public static Placement structure(String name,Map<Cell,String> mapping,Cell anchor,String purpose,List<String> tags){if(mapping.isEmpty())throw new IllegalArgumentException("Empty structure");if(anchor==null){var first=mapping.keySet().stream().min(Comparator.comparingInt((Cell c)->-c.z()).thenComparingInt(Cell::x).thenComparingInt(Cell::y).thenComparingInt(Cell::z)).orElseThrow();anchor=new Cell(first.x(),first.y(),first.z()+1);}var local=new ArrayList<Local>();var columns=new HashSet<Column>();for(var e:mapping.entrySet()){var c=e.getKey();local.add(new Local(c.x()-anchor.x(),c.y()-anchor.y(),anchor.z()-1-c.z(),e.getValue()));columns.add(new Column(c.x(),c.y()));}var s=new BotSchematic(name,List.of(List.of("#")),new Column(0,0),Map.of("#","team"),tags,purpose,"","deck",2,0,null,3,local,List.of());return new Placement(s,anchor,0,mapping,Set.of(),Set.of(),columns,null);}
}
